SELECT int16 = float64 AS c0, toTypeName(int16 = float64) AS t0, int16 != float64 AS c1, toTypeName(int16 != float64) AS t1, int16 < float64 AS c2, toTypeName(int16 < float64) AS t2, int16 <= float64 AS c3, toTypeName(int16 <= float64) AS t3, int16 > float64 AS c4, toTypeName(int16 > float64) AS t4, int16 >= float64 AS c5, toTypeName(int16 >= float64) AS t5 FROM he24.numeric ORDER BY row_id
